"""Data sources of this connector, declared by tool name (generated by connector-ontology-map migrate).

Served live as ``connector://resources``. Regenerate by editing the declarations, not the tools.
"""

# ruff: noqa: E501
from __future__ import annotations

from agent_connector_sdk.ingest.sources import IngestSourceDeclaration, IngestSourceSpec

CONNECTOR = "spark-mcp"

SOURCES = ()

SCHEMA_MAPPINGS = {
    "DatasetVersion": {
        "fields": {},
        "ontology_class": "Dataset",
    },
    "SparkApplication": {
        "fields": {},
        "ontology_class": None,
    },
    "SparkJob": {
        "fields": {},
        "ontology_class": "Action",
    },
    "Transform": {
        "fields": {},
        "ontology_class": None,
    },
    "TransformRun": {
        "fields": {},
        "ontology_class": None,
    },
}

RESOURCES = (
    {
        "id_prefix": "datasetversion",
        "label": "Dataset Version",
        "name": "DatasetVersion",
    },
    {
        "id_prefix": "sparkapplication",
        "label": "Spark Application",
        "name": "SparkApplication",
    },
    {
        "id_prefix": "sparkjob",
        "label": "Spark Job",
        "name": "SparkJob",
    },
    {
        "id_prefix": "transform",
        "label": "Transform",
        "name": "Transform",
    },
    {
        "id_prefix": "transformrun",
        "label": "Transform Run",
        "name": "TransformRun",
    },
)


def declaration() -> IngestSourceDeclaration:
    """The declaration the server assembles from this module."""
    specs = []
    for item in SOURCES:
        for entry in item["connector_sources"]:
            body = {k: v for k, v in entry.items() if k not in ("tool", "mapping")}
            specs.append(
                IngestSourceSpec.model_validate({**body, "tools": (entry["tool"],)})
            )
    return IngestSourceDeclaration.model_validate(
        {
            "connector": CONNECTOR,
            "sources": specs,
            "schema_mappings": SCHEMA_MAPPINGS,
            "resources": RESOURCES,
        }
    )
